def autocorrelation(series, lag):
    n = len(series)
    mean = sum(series) / n
    numerator = sum((series[i] - mean) * (series[i + lag] - mean) for i in range(n - lag))
    denominator = sum((x - mean) ** 2 for x in series)
    return round(numerator / denominator, 4)

